<?php $total=array_sum(array_map(fn($s)=>count($s['lessons']),$stages));$done=array_sum(array_column($stages,'completed_count'));$minutes=array_sum(array_map(fn($s)=>array_sum(array_column($s['lessons'],'duration_minutes')),$stages)); ?>
<a href="<?= e(route_url('/paths')) ?>" class="text-link small muted" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to learning paths</a>
<section class="map-hero"><div class="map-hero-copy"><span class="eyebrow orange-text"><?= e($path['category']) ?> · <?= e(ucfirst($path['difficulty'])) ?></span><h1><?= e($path['title']) ?></h1><p><?= e($path['description']) ?></p><div class="map-hero-meta"><span><?= icon('flag',15) ?> <?= count($stages) ?> stages</span><span><?= icon('book',15) ?> <?= $total ?> lessons</span><span><?= icon('clock',15) ?> <?= $minutes ?> min estimated</span><?php if($path['certificate_enabled']): ?><span><?= icon('award',15) ?> Earn a certificate</span><?php endif; ?></div><div style="margin-top:22px"><?php if(!$enrolled): ?><form action="<?= e(route_url('/api/paths/' . ((int)$path['id']) . '/enrol')) ?>" method="post" data-api><?= csrfField() ?><button class="btn btn-primary">Make this my next chapter <?= icon('arrow-right',16) ?></button></form><?php elseif($next): ?><a href="<?= e(route_url('/lessons/' . ((int)$next['id']))) ?>" class="btn btn-primary"><?= $done?'Continue learning':'Start my first lesson' ?> <?= icon('arrow-right',16) ?></a><?php else: ?><a href="#learning-map" class="btn btn-secondary">See my next requirements <?= icon('arrow-down',16) ?></a><?php endif; ?></div></div><?php require ROOT.'/app/Views/components/path-art.php'; ?></section>
<div class="map-layout"><div><div class="map-heading" id="learning-map"><h2>Your learning journey.</h2><div class="map-legend"><span><i class="legend-dot green-dot"></i>Completed</span><span><i class="legend-dot orange-dot"></i>Available</span><span><i class="legend-dot"></i>Locked</span></div></div><div class="map-stages"><?php foreach($stages as $i=>$stage): ?><section id="stage-<?= (int)$stage['id'] ?>" class="stage-card <?= e($stage['state']) ?>"><span class="stage-node"><?= icon(match($stage['state']){'completed'=>'check','mastered'=>'award','locked'=>'lock',default=>'flag'},21) ?></span><div class="stage-card-header"><div><span class="eyebrow">STAGE <?= $i+1 ?></span><h3><?= e($stage['title']) ?></h3><p><?= e($stage['description']) ?></p></div><?= badge($stage['state']) ?></div><?php if($stage['requirements']): ?><div class="locked-message"><?= icon('lock',16) ?><span>First complete <?= e(implode(', ',array_column($stage['requirements'],'title'))) ?>, including its required assessments.</span></div><?php endif; ?><div class="stage-content"><?php foreach($stage['lessons'] as $l): $locked=!$enrolled || $stage['state']==='locked' || $l['prerequisite_locked']; ?><<?= $locked?'div':'a' ?> <?= !$locked?'href="'.e(route_url('/lessons/'.(int)$l['id'])).'"':'' ?> class="stage-activity <?= $locked?'locked-item':'' ?>"><span class="<?= $l['completed_at']?'done':'' ?>"><?= icon($l['completed_at']?'check':($locked?'lock':'book'),15) ?></span><div><strong><?= e($l['title']) ?></strong><small><?= e($l['module_title']) ?> · <?= (int)$l['duration_minutes'] ?> min estimated</small></div><?= icon($locked?'lock':'chevron',14) ?></<?= $locked?'div':'a' ?>><?php endforeach; ?>
<?php foreach($stage['quizzes'] as $q): $locked=!$enrolled || $stage['state']==='locked'; ?><<?= $locked?'div':'a' ?> <?= !$locked?'href="'.e(route_url('/quizzes/'.(int)$q['id'])).'"':'' ?> class="stage-activity"><span class="<?= $q['passed']?'done':'' ?>"><?= icon($q['passed']?'check':'lightbulb',15) ?></span><div><strong><?= e($q['title']) ?></strong><small>Knowledge check · <?= (int)$q['passing_score'] ?>% to pass</small></div><?= badge($q['passed']?'passed':($q['required']?'required':'optional')) ?></<?= $locked?'div':'a' ?>><?php endforeach; ?>
<?php foreach($stage['assignments'] as $a): $locked=!$enrolled || $stage['state']==='locked'; ?><<?= $locked?'div':'a' ?> <?= !$locked?'href="'.e(route_url('/assignments/'.(int)$a['id'])).'"':'' ?> class="stage-activity"><span class="<?= $a['submission_status']==='accepted'?'done':'' ?>"><?= icon('briefcase',15) ?></span><div><strong><?= e($a['title']) ?></strong><small>Practical assignment · <?= $a['required']?'Required':'Optional' ?></small></div><?= icon($locked?'lock':'chevron',14) ?></<?= $locked?'div':'a' ?>><?php endforeach; ?>
<?php if(!$stage['lessons'] && !$stage['quizzes'] && !$stage['assignments']): ?><p class="fine-print" style="padding:15px 0">Activities for this stage are being prepared.</p><?php endif; ?></div></section><?php endforeach; ?></div><?php if(!$stages): emptyState('path','The path is taking shape.','Published activities will appear here as they become available.');endif; ?></div>
<aside class="map-aside"><?php $nodes=\Learnow\Repositories\DB::all('SELECT * FROM skill_nodes WHERE path_id=? ORDER BY id',[$path['id']]);$states=array_column($stages,'state','id'); if($nodes): ?><section class="card card-pad" style="margin-bottom:22px"><div class="card-header"><h2>Your growing skill tree.</h2><?= icon('path',18) ?></div><div class="skill-tree-nodes"><?php foreach($nodes as $node):$nodeState=$states[$node['stage_id']]??'locked';$parents=\Learnow\Repositories\DB::all('SELECT p.label FROM skill_connections c JOIN skill_nodes p ON p.id=c.prerequisite_node_id WHERE c.node_id=?',[$node['id']]); ?><a class="skill-tree-node <?= e($nodeState) ?>" href="#stage-<?= (int)$node['stage_id'] ?>"><span><?= icon(in_array($nodeState,['completed','mastered'])?'check':($nodeState==='locked'?'lock':'path'),16) ?></span><div><strong><?= e($node['label']) ?></strong><?php if($parents): ?><small>After <?= e(implode(' + ',array_column($parents,'label'))) ?></small><?php else: ?><small><?= e(ucwords(str_replace('_',' ',$nodeState))) ?></small><?php endif; ?></div></a><?php endforeach; ?></div><p class="fine-print" style="margin-top:14px">Branches use server-checked stage and skill prerequisites.</p></section><?php endif; ?><section class="card card-pad" style="margin-bottom:22px"><div class="card-header"><h2>What you’ll walk away with.</h2></div><ul class="objective-list"><?php foreach(lines($path['objectives']) as $item): ?><li><?= icon('check-circle',15) ?><span><?= e($item) ?></span></li><?php endforeach; ?></ul></section><section class="card card-pad" style="margin-bottom:22px"><div class="card-header"><h2>Your little wins.</h2><?= icon('chart',18) ?></div><div class="course-progress-label"><span><?= $done ?> of <?= $total ?> lessons</span><strong><?= $total?round($done/$total*100):0 ?>%</strong></div><div class="progress-track"><span style="width:<?= $total?round($done/$total*100):0 ?>%"></span></div><p class="fine-print">Stage completion also includes required quizzes and accepted assignments. Your progress is checked on the server.</p></section><?php if($path['certificate_enabled']): ?><section class="card card-pad"><span class="icon-tile orange" style="margin-bottom:15px"><?= icon('award',23) ?></span><h3 style="font-size:15px;margin-bottom:10px">Make the milestone yours.</h3><p class="fine-print">Complete every required activity<?= $path['certificate_min_score']?' and achieve a '.(int)$path['certificate_min_score'].'% assessment average':'' ?> to earn your certificate. Enrolment alone is not enough.</p><?php if($enrolled): ?><form action="<?= e(route_url('/api/certificates/' . ((int)$path['id']))) ?>" method="post" data-api style="margin-top:18px"><?= csrfField() ?><button class="btn btn-secondary btn-small btn-block">Check certificate eligibility <?= icon('arrow-right',14) ?></button></form><?php endif; ?></section><?php endif; ?></aside></div>
